export type RuleSeverity = 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW';

export interface TriggeredRule {
  ruleId: string;
  ruleName: string;
  severity: RuleSeverity;
  category: 'STRUCTURING' | 'RAPID_MOVEMENT' | 'GEO_ANOMALY' | 'HIGH_VELOCITY' | 'UNUSUAL_VOLUME' | string;
  description: string;
  matchedConditions: Record<string, unknown>;
}

/**
 * DetectionResult contract generated by Member 2's detection engine
 * and consumed by Member 4's Investigate module.
 */
export interface DetectionResult {
  resultId: string;
  engineVersion: string;
  timestamp: string; // ISO 8601
  overallRiskScore: number; // 0-100 investigation priority
  triggeredRules: TriggeredRule[];
  anomalyFeatures?: Record<string, number>;
}
